# Custom training loop that handles corrupted images
def safe_fit_model(model, generator, validation_data, epochs, callbacks):
    from tensorflow.keras.callbacks import Callback

    # Replace callbacks with a custom callback wrapper
    class SafeTraining(Callback):
        def __init__(self, original_callbacks):
            self.original_callbacks = original_callbacks
            self.epoch = 0

        def on_epoch_begin(self, epoch, logs=None):
            self.epoch = epoch
            for cb in self.original_callbacks:
                cb.on_epoch_begin(epoch, logs)

        def on_batch_begin(self, batch, logs=None):
            for cb in self.original_callbacks:
                if hasattr(cb, 'on_batch_begin'):
                    cb.on_batch_begin(batch, logs)

        def on_batch_end(self, batch, logs=None):
            for cb in self.original_callbacks:
                if hasattr(cb, 'on_batch_end'):
                    cb.on_batch_end(batch, logs=None)

        def on_epoch_end(self, epoch, logs=None):
            for cb in self.original_callbacks:
                cb.on_epoch_end(epoch, logs)

    safe_callbacks = SafeTraining(callbacks)

    history = {'loss': [], 'accuracy': [], 'val_loss': [], 'val_accuracy': []}

    for epoch in range(epochs):
        print(f'Epoch {epoch + 1}/{epochs}')
        safe_callbacks.on_epoch_begin(epoch)

        # Training
        train_loss = []
        train_acc = []
        batch_count = 0

        while batch_count < len(generator):
            try:
                x_batch, y_batch = generator.next()
                metrics = model.train_on_batch(x_batch, y_batch)
                train_loss.append(metrics[0])
                train_acc.append(metrics[1])
                batch_count += 1

                safe_callbacks.on_batch_end(batch_count, {'loss': metrics[0], 'accuracy': metrics[1]})

            except Exception as e:
                print(f"Warning: Skipping corrupted batch in training. Error: {e}")
                batch_count += 1
                continue

        # Validation
        val_loss = []
        val_acc = []
        val_batch_count = 0

        while val_batch_count < len(validation_data):
            try:
                x_batch, y_batch = validation_data.next()
                metrics = model.test_on_batch(x_batch, y_batch)
                val_loss.append(metrics[0])
                val_acc.append(metrics[1])
                val_batch_count += 1

            except Exception as e:
                print(f"Warning: Skipping corrupted batch in validation. Error: {e}")
                val_batch_count += 1
                continue

        # Calculate average metrics
        avg_train_loss = np.mean(train_loss) if train_loss else 0
        avg_train_acc = np.mean(train_acc) if train_acc else 0
        avg_val_loss = np.mean(val_loss) if val_loss else 0
        avg_val_acc = np.mean(val_acc) if val_acc else 0

        history['loss'].append(avg_train_loss)
        history['accuracy'].append(avg_train_acc)
        history['val_loss'].append(avg_val_loss)
        history['val_accuracy'].append(avg_val_acc)

        print(f' - loss: {avg_train_loss:.4f} - accuracy: {avg_train_acc:.4f} - '
              f'val_loss: {avg_val_loss:.4f} - val_accuracy: {avg_val_acc:.4f}')

        logs = {'loss': avg_train_loss, 'accuracy': avg_train_acc, 
                'val_loss': avg_val_loss, 'val_accuracy': avg_val_acc}
        safe_callbacks.on_epoch_end(epoch, logs)

        # Reset generators
        generator.reset()
        validation_data.reset()

    # Create history-like object
    class History:
        def __init__(self, history):
            self.history = history
    return History(history)


